// Sonderwunsch Hammer: Sturm-Hinweis auf der Startseite
const WIND_GRENZE = 50; // km/h, ab hier kein Dach betreten

function sturmHinweis(wind) {
  if (wind < WIND_GRENZE) return;
  app.hinweis(`Windwarnung: ${wind} km/h – Dacharbeiten pausieren`);
}

sturmHinweis(62);
